package com.dentalclinic.patientcare.service;
import com.dentalclinic.patientcare.entity.*;import com.dentalclinic.patientcare.exception.ResourceNotFoundException;import com.dentalclinic.patientcare.repository.*;import org.springframework.stereotype.Service;import java.time.*;import java.util.*;
@Service public class PatientCareService {private final PatientCareRecordRepository patients;private final CareHistoryRepository history;private final ConsentRecordRepository consents;private final PatientSubmissionRepository submissions;public PatientCareService(PatientCareRecordRepository p,CareHistoryRepository h,ConsentRecordRepository c,PatientSubmissionRepository s){patients=p;history=h;consents=c;submissions=s;}
public List<PatientCareRecord> patients(String search,Boolean active){if(search!=null&&!search.isBlank())return patients.findByFullNameContainingIgnoreCase(search);if(active!=null)return patients.findByActive(active);return patients.findAll();} public PatientCareRecord patient(Long id){return patients.findById(id).orElseThrow(()->new ResourceNotFoundException("Patient record not found: "+id));} public PatientCareRecord save(PatientCareRecord p){validateGuardian(p);return patients.save(p);} public PatientCareRecord update(Long id,PatientCareRecord in){PatientCareRecord p=patient(id);p.setFullName(in.getFullName());p.setDateOfBirth(in.getDateOfBirth());p.setPhone(in.getPhone());p.setEmail(in.getEmail());p.setAddress(in.getAddress());p.setMedicalConditions(in.getMedicalConditions());p.setMedications(in.getMedications());p.setAllergies(in.getAllergies());p.setDentalNotes(in.getDentalNotes());p.setGuardianPatientId(in.getGuardianPatientId());p.setActive(in.getActive());p.setNextRecallDate(in.getNextRecallDate());validateGuardian(p);return patients.save(p);} public void delete(Long id){PatientCareRecord p=patient(id);p.setActive(false);patients.save(p);} private void validateGuardian(PatientCareRecord p){if(p.getGuardianPatientId()!=null){if(p.getId()!=null&&p.getId().equals(p.getGuardianPatientId()))throw new IllegalArgumentException("Patient cannot be their own guardian");patient(p.getGuardianPatientId());}}
public List<CareHistoryEntry> history(Long pid){patient(pid);return history.findByPatientIdOrderByVisitDateDesc(pid);}public CareHistoryEntry addHistory(Long pid,CareHistoryEntry x){patient(pid);x.setPatientId(pid);return history.save(x);}public void deleteHistory(Long id){history.deleteById(id);}public List<ConsentRecord> consents(Long pid){patient(pid);return consents.findByPatientIdOrderByConsentDateDesc(pid);}public ConsentRecord addConsent(Long pid,ConsentRecord x){patient(pid);x.setPatientId(pid);return consents.save(x);}public void deleteConsent(Long id){consents.deleteById(id);}public List<PatientCareRecord> recalls(int days){LocalDate now=LocalDate.now();return patients.findByNextRecallDateBetween(now,now.plusDays(days));}public PatientSubmission submit(Long pid,PatientSubmission x){patient(pid);x.setPatientId(pid);if(x.getType()==PatientSubmission.Type.FEEDBACK&&x.getRating()==null)throw new IllegalArgumentException("Rating is required for feedback");return submissions.save(x);}public List<PatientSubmission> submissions(Long pid){patient(pid);return submissions.findByPatientIdOrderBySubmittedAtDesc(pid);}}
